    permute(nums, 0, new ArrayList<>(), permutations);

    return permutations;
}

private void permute(int[] nums, int start, List<Integer> current, List<List<Integer>> permutations) {
    if (start == nums.length) {
        permutations.add(new ArrayList<>(current));
        return;
    }

    for (int i = start; i < nums.length; i++) {
        current.add(nums[i]);
        permute(nums, i + 1, current, permutations);
        current.remove(current.size() - 1);
    }
}

