public int minOperations(int n) {
  int[] arr = new int[n];
  for (int i = 0; i < n; i++) {
    arr[i] = (2 * i) + 1;
  }

  int minOperations = 0;
  while (arr[0] != arr[n - 1]) {
    int x = -1, y = -1;
    for (int i = 0; i < n; i++) {
      if (arr[i] != arr[n - 1]) {
        x = i;
        break;
      }
    }

    for (int i = 0; i < n; i++) {
      if (arr[i] != arr[n - 1]) {
        y = i;
        break;
      }
    }

    arr[x] -= 1;
    arr[y] += 1;
    minOperations++;
  }

  return minOperations;
}

