public int kthFactor(int n, int k) {
    // Find the factors of n
    int[] factors = factorize(n);

    // Check if k is in range
    if (k > factors.length) {
        return -1;
    }

    // Return the kth factor
    return factors[k - 1];
}

private int[] factorize(int n) {
    // Initialize an array to store the factors
    int[] factors = new int[n];

    // Iterate from 1 to n
    for (int i = 1; i <= n; i++) {
        // Check if i divides n evenly
        if (n % i == 0) {
            // Add i to the array of factors
            factors.push(i);
        }
    }

    // Return the array of factors
    return factors;
}

