    Arrays.sort(A);

    // loop through the array and calculate the sum of each pair of adjacent elements
    for (int i = 0; i < A.length - 1; i++) {
        int sum = A[i] + A[i + 1];

        // check if the sum is a perfect square
        if (Math.sqrt(sum) % 1 == 0) {
            count++;
        }
    }

    // return the number of square permutations
    return count;
}

