      int uglies = Math.min(Math.min(uglyNumbers[index2] * 2, uglyNumbers[index3] * 3), uglyNumbers[index5] * 5);
      uglyNumbers[i] = uglies;
      if (uglyNumbers[i] == uglyNumbers[index2] * 2) {
        index2++;
      }
      if (uglyNumbers[i] == uglyNumbers[index3] * 3) {
        index3++;
      }
      if (uglyNumbers[i] == uglyNumbers[index5] * 5) {
        index5++;
      }
    }
    return uglyNumbers[n];
  }

public static int calculateEnergy(String s) {
    int energy = 0;
    int current = 0;
    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(current)) {
            current++;
            energy = Math.max(energy, current);
        } else {
            current = 1;
        }
    }
    return energy;
}

public List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        result.add(i);
    }
    Collections.sort(result);
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    Set<Integer> uniqueElements = new HashSet<>();
    int sum = 0;
    for (int num : nums) {
        if (uniqueElements.add(num)) {
            sum += num;
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    // Initialize an array to store the counts of perfect square numbers
    int[] count = new int[n+1];

    // Initialize the first element of the array to 1, since 1 is a perfect square
    count[1] = 1;

    // Iterate from 2 to n, and for each element, count the number of perfect square numbers that add up to it
    for (int i = 2; i <= n; i++) {
        for (int j = 1; j*j <= i; j++) {
            count[i] = count[i] + count[i - j*j];
        }
    }

    // Return the minimum count of perfect square numbers
    return count[n];
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder builder = new StringBuilder();
    for (String word : words) {
        builder.append(new StringBuffer(word).reverse().toString());
    }
    return builder.toString();
}
